select * from (
    select A.*,M.MACHINE_NAME from t_tm_quota_setting A LEFT JOIN T_TM_MACHINE_INFO M
    ON A.machine_id=M.ID
    WHERE A.del_flag='0'
    and INSTR(A.tread_code, #{treadCode,jdbcType=VARCHAR}) > 0
    and A.machine_id = #{machineId,jdbcType=DECIMAL}
    order by A.create_time desc
)

    order by ${orderStr}

mapper.update:
update t_tm_quota_setting
tread_code = #{treadCode,jdbcType=VARCHAR}, machine_id = #{machineId,jdbcType=DECIMAL}, quota = #{quota,jdbcType=DECIMAL}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, remark = #{remark,jdbcType=VARCHAR},
where id = #{id}

