mapper.insert:
insert into t_tm_quota_setting (id, tread_code, machine_id, quota, create_by, create_time, del_flag, remark) select SEQ_QUOTA_SETTING.NEXTVAL AS ID, x.* from (
select #{QuotaSetting.treadCode,jdbcType=VARCHAR}, #{QuotaSetting.machineId,jdbcType=DOUBLE}, #{QuotaSetting.quota,jdbcType=DOUBLE}, #{QuotaSetting.createBy}, #{QuotaSetting.createTime}, #{QuotaSetting.delFlag}, #{QuotaSetting.remark,jdbcType=VARCHAR} from dual
) x

mapper.update:
merge into t_tm_quota_setting a USING (
select #{QuotaSetting.treadCode,jdbcType=VARCHAR} tread_code, #{QuotaSetting.machineId,jdbcType=DOUBLE} machine_id, #{QuotaSetting.quota,jdbcType=DOUBLE} quota, #{QuotaSetting.createBy,jdbcType=VARCHAR} create_by, #{QuotaSetting.createTime,jdbcType=DATE} create_time, #{QuotaSetting.updateBy,jdbcType=VARCHAR} update_by, #{QuotaSetting.updateTime,jdbcType=DATE} update_time, #{QuotaSetting.remark,jdbcType=VARCHAR} remark from dual
) b ON ( ((b.tread_code is null and a.tread_code is null) or (a.tread_code = b.tread_code)) and ((b.machine_id is null and a.machine_id is null) or(b.machine_id = a.machine_id)) AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.quota = b.quota, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.tread_code, a.machine_id, a.quota, a.create_by, a.create_time, a.remark, a.del_flag) values (SEQ_QUOTA_SETTING.NEXTVAL, b.tread_code, b.machine_id, b.quota, b.create_by, sysdate, b.remark, '0')
